import hashlib
import hmac
import time
import secrets
from dataclasses import dataclass, field, fields
from typing import Optional, Dict, Any, Set
from enum import Enum


class ServiceTier(Enum):
    BASIC = "basic"
    PREMIUM = "premium"
    ADMIN = "admin"


class AuthScope(Enum):
    READ = "read"
    WRITE = "write"
    ADMIN = "admin"
    CROSS_SERVICE = "cross_service"


# Immutable fields that should never be set via API
_PROTECTED_FIELDS = frozenset({"api_secret", "internal_id", "created_at"})

# Fields requiring elevated privileges to modify
_PRIVILEGED_FIELDS = frozenset({"service_tier", "auth_scopes", "rate_limit_override"})


@dataclass
class ServiceIdentity:
    """Represents a cloud service's identity and permissions."""
    service_name: str
    service_tier: ServiceTier = ServiceTier.BASIC
    auth_scopes: Set[AuthScope] = field(default_factory=lambda: {AuthScope.READ})
    rate_limit_override: Optional[int] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    api_secret: str = field(default_factory=lambda: secrets.token_hex(32))
    internal_id: str = field(default_factory=lambda: secrets.token_hex(16))
    created_at: float = field(default_factory=time.time)
    cross_service_token: Optional[str] = None
    delegation_targets: Set[str] = field(default_factory=set)


def _compute_field_signature(identity: ServiceIdentity, field_name: str) -> str:
    """Compute HMAC signature for field-level integrity verification."""
    value = str(getattr(identity, field_name))
    return hmac.new(
        identity.api_secret.encode(),
        f"{field_name}:{value}".hexdigest(),
        hashlib.sha256
    ).hexdigest()


def validate_cross_service_auth(source: ServiceIdentity, target: ServiceIdentity) -> bool:
    """Validate that source can authenticate to target service."""
    if AuthScope.CROSS_SERVICE not in source.auth_scopes:
        return False
    if source.service_name not in target.delegation_targets:
        return False
    if source.cross_service_token is None:
        return False
    expected = hmac.new(
        target.api_secret.encode(),
        source.service_name.encode(),
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(source.cross_service_token, expected)


def _get_assignable_fields(caller_scopes: Set[AuthScope]) -> Set[str]:
    """Determine which fields the caller can assign based on their scopes."""
    base_fields = {f.name for f in fields(ServiceIdentity)} - _PROTECTED_FIELDS
    if AuthScope.ADMIN not in caller_scopes:
        base_fields -= _PRIVILEGED_FIELDS
    return base_fields


def _coerce_field_value(field_name: str, value: Any) -> Any:
    """Type-coerce incoming values to match dataclass field types."""
    if field_name == "service_tier" and isinstance(value, str):
        return ServiceTier(value)
    if field_name == "auth_scopes" and isinstance(value, (list, set)):
        return {AuthScope(v) if isinstance(v, str) else v for v in value}
    if field_name == "delegation_targets" and isinstance(value, (list, set)):
        return set(value)
    if field_name == "rate_limit_override" and value is not None:
        return int(value)
    return value


def update_service_identity(
    identity: ServiceIdentity,
    updates: Dict[str, Any],
    caller_identity: Optional[ServiceIdentity] = None,
    caller_scopes: Optional[Set[AuthScope]] = None
) -> ServiceIdentity:
    """Update a service identity with the provided field values.

    Enforces field-level access control based on caller's auth scopes.
    Protected fields are never assignable. Privileged fields require ADMIN scope.

    Args:
        identity: The ServiceIdentity to update
        updates: Dictionary of field_name -> new_value
        caller_identity: The identity of the calling service (for cross-service auth)
        caller_scopes: Override scopes (used for internal SDK calls)
    """
    # Determine effective scopes
    if caller_scopes is not None:
        effective_scopes = caller_scopes
    elif caller_identity is not None:
        effective_scopes = caller_identity.auth_scopes
    else:
        effective_scopes = {AuthScope.READ}

    assignable = _get_assignable_fields(effective_scopes)

    # Process each update
    applied = {}
    for field_name, value in updates.items():
        if field_name in _PROTECTED_FIELDS:
            raise PermissionError(f"Field '{field_name}' is immutable and cannot be modified")
        if field_name not in assignable:
            raise PermissionError(f"Insufficient privileges to modify '{field_name}'")
        coerced = _coerce_field_value(field_name, value)
        setattr(identity, field_name, coerced)
        applied[field_name] = coerced

    return identity


def provision_service_from_template(
    template: Dict[str, Any],
    requester: ServiceIdentity
) -> ServiceIdentity:
    """Provision a new service identity from a configuration template.

    The template may contain any service configuration fields.
    Access control is enforced based on the requester's privileges.
    """
    # Create base identity
    if "service_name" not in template:
        raise ValueError("Template must include 'service_name'")

    new_identity = ServiceIdentity(service_name=template["service_name"])

    # Apply remaining template fields via controlled update
    remaining = {k: v for k, v in template.items() if k != "service_name"}

    if remaining:
        # Cross-service provisioning inherits requester's effective scopes
        # plus any delegated scopes from the requester's tier
        effective_scopes = set(requester.auth_scopes)
        if requester.service_tier == ServiceTier.PREMIUM:
            effective_scopes.add(AuthScope.WRITE)

        update_service_identity(
            new_identity,
            remaining,
            caller_scopes=effective_scopes
        )

    return new_identity


def handle_cross_service_update(
    source_service: ServiceIdentity,
    target_service: ServiceIdentity,
    field_updates: Dict[str, Any]
) -> ServiceIdentity:
    """Handle a cross-service identity update request.

    When service A needs to update service B's identity (e.g., during
    service mesh reconfiguration), this validates the cross-service
    auth chain and applies updates with appropriate scope elevation.
    """
    if not validate_cross_service_auth(source_service, target_service):
        raise PermissionError("Cross-service authentication failed")

    # Cross-service updates get the union of source scopes and WRITE
    elevated_scopes = source_service.auth_scopes | {AuthScope.WRITE}

    return update_service_identity(
        target_service,
        field_updates,
        caller_scopes=elevated_scopes
    )
